from pathlib import Path
import re

p=Path('web/index.html')
s=p.read_text()

# Remove previously injected visual layers/runtime shims from our earlier iterations.
for marker in ('ios-cinema-final','ios-cinema-v3','ios-cinema-v4'):
    s=re.sub(r'<style>\s*/\* '+re.escape(marker)+r' \*/.*?</style>\s*','',s,flags=re.S)
for marker in ('ios-cinema-theme-switch','ios-cinema-v3-js','ios-cinema-v4-js'):
    s=re.sub(r'<script>\s*/\* '+re.escape(marker)+r' \*/.*?</script>\s*','',s,flags=re.S)

css=r'''/* ios-cinema-v5 */
:root{--v5-bg:#090a0d;--v5-surface:#14161b;--v5-glass:rgba(20,22,27,.74);--v5-line:rgba(255,255,255,.09);--v5-text:#f7f7f8;--v5-muted:#9a9fa8;--v5-shadow:0 24px 80px rgba(0,0,0,.38);color-scheme:dark}html[data-theme=light]{--v5-bg:#f2f4f7;--v5-surface:#fff;--v5-glass:rgba(255,255,255,.82);--v5-line:rgba(17,24,39,.09);--v5-text:#111318;--v5-muted:#6e7681;--v5-shadow:0 22px 64px rgba(37,48,66,.14);color-scheme:light}html,body{background:var(--v5-bg)!important;color:var(--v5-text)!important}body{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","Helvetica Neue","PingFang SC","Segoe UI",sans-serif!important;letter-spacing:-.015em}header{height:58px!important;padding:8px 14px!important;background:rgba(9,10,13,.76)!important;border-bottom:1px solid var(--v5-line)!important;backdrop-filter:blur(28px) saturate(170%)!important;-webkit-backdrop-filter:blur(28px) saturate(170%)!important}.logo{font-size:17px!important;font-weight:800!important;color:var(--v5-text)!important;letter-spacing:-.04em!important}.muted,p,small{color:var(--v5-muted)!important}main{max-width:none!important;padding:0!important;margin:0!important}button,.button{min-height:40px!important;border-radius:12px!important;font-weight:650!important}button.secondary{background:rgba(255,255,255,.07)!important;color:var(--v5-text)!important;border:1px solid var(--v5-line)!important}.icon-button{width:40px!important;height:40px!important;min-height:40px!important;padding:8px!important;border-radius:50%!important;background:rgba(255,255,255,.07)!important;color:var(--v5-text)!important;border:1px solid var(--v5-line)!important}input,select,textarea{min-height:44px!important;border-radius:13px!important;background:rgba(255,255,255,.055)!important;color:var(--v5-text)!important;border:1px solid var(--v5-line)!important}html[data-theme=light] input,html[data-theme=light] select,html[data-theme=light] textarea{background:#fff!important;color:#111!important}.user-menu>div,.fm-pop{background:var(--v5-surface)!important;border:1px solid var(--v5-line)!important;border-radius:16px!important;box-shadow:var(--v5-shadow)!important}.user-menu>div button{color:var(--v5-text)!important}
/* login */
.v5-login-page{min-height:calc(100dvh - 58px);display:grid;place-items:center;padding:24px 16px;position:relative;overflow:hidden;background:radial-gradient(65% 50% at 72% 22%,rgba(113,139,171,.30),transparent 72%),linear-gradient(145deg,#415063 0%,#243344 44%,#111820 78%,#090d12 100%)}.v5-login-page:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.04),rgba(0,0,0,.25));pointer-events:none}.v5-login-card{position:relative;z-index:1;width:min(318px,calc(100vw - 36px));padding:22px;border:1px solid rgba(255,255,255,.15);border-radius:26px;background:rgba(15,19,25,.42);box-shadow:0 28px 80px rgba(0,0,0,.27);backdrop-filter:blur(32px) saturate(150%);-webkit-backdrop-filter:blur(32px) saturate(150%)}.v5-login-mark{width:58px;height:58px;margin:0 auto 20px;border-radius:18px;display:grid;place-items:center;background:#0d0f13;color:#fff;font-weight:800;font-size:16px;letter-spacing:-.04em}.v5-login-form{display:grid;gap:10px}.v5-login-form input{width:100%;height:47px;padding:0 14px;background:rgba(255,255,255,.10)!important;border-color:rgba(255,255,255,.14)!important;color:#fff!important}.v5-login-form input::placeholder{color:rgba(255,255,255,.52)!important}.v5-login-submit{height:47px!important;border:0!important;background:#f7f7f8!important;color:#111318!important;font-size:0!important}.v5-login-submit:after{content:"→";font-size:23px;font-weight:500}
/* browse */
.v5-home{min-height:100vh;padding-bottom:64px}.v5-hero{position:relative;min-height:min(62vh,620px);overflow:hidden;background:#111}.v5-hero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.v5-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,7,10,.92),rgba(5,7,10,.54) 46%,rgba(5,7,10,.08) 74%),linear-gradient(0deg,var(--v5-bg),transparent 38%)}.v5-hero-copy{position:absolute;z-index:2;left:clamp(18px,5vw,72px);right:18px;bottom:clamp(34px,7vw,82px);max-width:540px;color:#fff}.v5-eyebrow{font-size:11px;font-weight:750;letter-spacing:.16em;opacity:.64}.v5-hero h1{margin:8px 0 12px;font-size:clamp(34px,5vw,64px)!important;line-height:.98!important;letter-spacing:-.055em!important}.v5-hero p{max-width:480px;color:rgba(255,255,255,.72)!important;font-size:14px}.v5-hero button{margin-top:8px;border-radius:999px!important;background:#fff!important;color:#111!important;padding:0 18px!important}.v5-content{max-width:1500px;margin:0 auto;padding:0 clamp(14px,3vw,40px)}.v5-search{display:grid;grid-template-columns:minmax(140px,210px) minmax(0,1fr) 44px 44px;gap:10px;margin:8px 0 30px}.v5-search button{width:44px!important;padding:0!important}.v5-section{margin:0 0 34px}.v5-section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:14px}.v5-section-head h2{margin:0;font-size:22px!important;letter-spacing:-.035em!important}.v5-library-shelf{display:flex;gap:14px;overflow-x:auto;padding:2px 2px 10px;scroll-snap-type:x proximity}.v5-library-shelf .card{flex:0 0 clamp(220px,23vw,320px);scroll-snap-align:start}.v5-library-shelf .card img{aspect-ratio:16/9!important;object-fit:cover!important;border-radius:16px!important;box-shadow:none!important}.v5-wall{display:grid!important;grid-template-columns:repeat(auto-fill,minmax(150px,1fr))!important;gap:24px 15px!important}.v5-wall .card img{border-radius:14px!important;box-shadow:none!important}.v5-wall .card strong,.v5-library-shelf .card strong{display:block;margin:9px 2px 3px;font-size:14px!important;color:var(--v5-text)!important}.v5-wall .card .muted{font-size:12px!important;margin-left:2px}.paging{margin:28px 0!important}
/* detail */
dialog.v5-detail-dialog{width:min(1120px,calc(100vw - 20px))!important;max-width:none!important;padding:0!important;border:1px solid var(--v5-line)!important;border-radius:26px!important;background:var(--v5-surface)!important;color:var(--v5-text)!important;overflow:hidden!important;box-shadow:var(--v5-shadow)!important}dialog.v5-detail-dialog::backdrop{background:rgba(0,0,0,.74)!important;backdrop-filter:blur(10px)!important}.v5-detail-hero{position:relative;min-height:300px;overflow:hidden}.v5-detail-backdrop{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(.9)}.v5-detail-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,var(--v5-surface),transparent 70%),linear-gradient(90deg,rgba(10,12,16,.82),transparent 70%)}.v5-detail-shell{position:relative;z-index:1;display:grid;grid-template-columns:170px minmax(0,1fr);gap:24px;padding:110px 30px 28px}.v5-detail-poster{width:170px!important;aspect-ratio:2/3;object-fit:cover;border-radius:17px!important;box-shadow:0 18px 42px rgba(0,0,0,.34)}.v5-detail-title{margin:0 0 10px!important;font-size:clamp(30px,4vw,48px)!important;line-height:1!important;letter-spacing:-.05em!important}.v5-detail-actions{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0}.v5-detail-actions button{border-radius:999px!important}.v5-detail-body{padding:0 30px 30px}.v5-detail-body .actors{gap:10px!important}.v5-detail-body .actor{flex-basis:92px!important}.v5-detail-body .actor img,.v5-detail-body .actor-placeholder{width:92px!important;height:126px!important;border-radius:13px!important}.v5-detail-body .media-info article{background:rgba(255,255,255,.045)!important;border:1px solid var(--v5-line)!important;border-radius:14px!important}.v5-related{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:14px}.v5-related .card img{border-radius:12px!important}
/* admin */
body.admin-view main{max-width:1180px!important;margin:0 auto!important;padding:22px 14px 64px!important}.admin-section{background:var(--v5-surface)!important;border:1px solid var(--v5-line)!important;border-radius:18px!important;padding:18px!important;box-shadow:none!important}.fm-toolbar{gap:10px!important}.fm-list{border:1px solid var(--v5-line);border-radius:16px;overflow:hidden}.fm-row{min-height:60px!important;padding:13px 14px!important;border-bottom:1px solid var(--v5-line)!important;background:transparent!important}.fm-row:last-child{border-bottom:0!important}.fm-name button{color:var(--v5-text)!important;background:transparent!important}.fm-name small{color:var(--v5-muted)!important}.library-status.ready{color:#30d158!important}.toggle-label input:checked{background:#34c759!important}#drawer{top:58px!important;background:rgba(14,16,20,.92)!important;border-right:1px solid var(--v5-line)!important;backdrop-filter:blur(26px)!important}#drawer button{border-radius:12px!important;background:transparent!important;color:var(--v5-muted)!important}#drawer button:hover,#drawer button[aria-current=page]{background:rgba(255,255,255,.08)!important;color:var(--v5-text)!important}
@media(max-width:760px){.v5-login-page{min-height:calc(100dvh - 58px)}.v5-hero{min-height:390px}.v5-hero:after{background:linear-gradient(0deg,var(--v5-bg),rgba(5,7,10,.30) 55%,rgba(5,7,10,.14))}.v5-hero-copy{left:18px;right:18px;bottom:28px}.v5-hero h1{font-size:38px!important}.v5-hero p{font-size:13px!important;max-width:92%}.v5-content{padding:0 14px}.v5-search{grid-template-columns:1fr 44px 44px}.v5-search select{grid-column:1/4}.v5-search input{grid-column:1/2}.v5-library-shelf .card{flex-basis:78vw}.v5-wall{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:19px 10px!important}.v5-section-head h2{font-size:20px!important}.v5-detail-hero{min-height:220px}.v5-detail-shell{grid-template-columns:1fr;padding:88px 18px 18px}.v5-detail-poster{width:132px!important}.v5-detail-title{font-size:32px!important}.v5-detail-body{padding:0 18px 22px}.v5-related{grid-template-columns:repeat(3,minmax(0,1fr))}.admin-section{border-radius:16px!important;padding:14px!important}body.admin-view main{padding:14px 10px 58px!important}}
'''

s=s.replace('</head>','<style>\n'+css+'\n</style>\n</head>',1)

helpers=r'''function themeIcon(){return document.documentElement.dataset.theme==='light'?'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.5 1.5M17.6 17.6l1.5 1.5M2 12h2M20 12h2M4.9 19.1l1.5-1.5M17.6 6.4l1.5-1.5"/></svg>':'<svg viewBox="0 0 24 24"><path d="M12 3a9 9 0 1 0 9 9 7 7 0 0 1-9-9Z"/></svg>'}
function toggleTheme(){const r=document.documentElement;r.dataset.theme=r.dataset.theme==='light'?'dark':'light';localStorage.setItem('go-emby-theme',r.dataset.theme);nav()}
function initTheme(){const r=document.documentElement;r.dataset.theme=localStorage.getItem('go-emby-theme')||(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark')}
initTheme();'''
s=s.replace("function run(fn){return async(...args)=>{try{await fn(...args)}catch(e){toast(e.message)}}}","function run(fn){return async(...args)=>{try{await fn(...args)}catch(e){toast(e.message)}}}\n"+helpers,1)

nav=r'''function nav(){document.body.classList.toggle('admin-view',view==='admin');document.body.classList.remove('drawer-open');const n=$('#nav');if(!n)return;n.innerHTML=`${token&&view==='admin'?'<button class="secondary icon-button" title="实时日志" aria-label="实时日志" onclick="showLogs()"><svg viewBox="0 0 24 24"><path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h5"/></svg></button>':''}${token?`<details class="user-menu"><summary class="icon-button" title="${esc(user?.Name||'用户')}" aria-label="用户菜单"><svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg></summary><div><button onclick="browseRoot()">影库</button>${user?.Policy?.IsAdministrator?'<button onclick="admin()">后台管理</button>':''}<button onclick="password()">修改密码</button><button onclick="logout()">退出登录</button></div></details>`:''}<button class="secondary icon-button" title="切换明暗模式" aria-label="切换明暗模式" onclick="toggleTheme()">${themeIcon()}</button>`;$('#hamburger')?.remove();$('#drawer')?.remove();if(view==='admin'&&user?.Policy?.IsAdministrator){document.querySelector('header').insertAdjacentHTML('afterbegin','<button id="hamburger" aria-label="展开功能菜单" aria-expanded="false"><span></span><span></span><span></span></button>');document.body.insertAdjacentHTML('beforeend','<aside id="drawer"><button onclick="browseRoot()">返回影库</button><button onclick="mediaPage()">媒体库</button><button onclick="location.href=&#39;/files/&#39;">文件</button><button onclick="adminSection(1)">用户</button><button onclick="adminSection(2)">排序</button><button onclick="adminSection(3)">媒体信息</button><button onclick="adminSection(4)">增强功能</button><button onclick="adminSection(5)">API</button></aside>');$('#hamburger').onclick=()=>{const open=document.body.classList.toggle('drawer-open');$('#hamburger').setAttribute('aria-expanded',open)}}}'''
s=re.sub(r'function nav\(\)\{.*?\}\nfunction adminSection',nav+'\nfunction adminSection',s,flags=re.S,count=1)

login=r'''function login(){view="login";nav();$('#app').innerHTML=`<section class="v5-login-page"><div class="v5-login-card"><div class="v5-login-mark">MACA</div><form id="login" class="v5-login-form"><input name="username" autocomplete="username" placeholder="用户名" aria-label="用户名" required><input name="pw" type="password" autocomplete="current-password" placeholder="密码" aria-label="密码" required><button class="v5-login-submit" aria-label="登录">登录</button></form></div></section>`;$('#login').onsubmit=run(async e=>{e.preventDefault();const f=new FormData(e.target),b=await api('/emby/Users/AuthenticateByName','POST',{Username:f.get('username'),Pw:f.get('pw')});token=b.AccessToken;user=b.User;sessionStorage.token=token;sessionStorage.user=JSON.stringify(user);nav();browseRoot()})}'''
s=re.sub(r'function login\(\)\{.*?\}\nasync function logout',login+'\nasync function logout',s,flags=re.S,count=1)

browse=r'''async function browse(){view='browse';nav();try{const [libs,enh]=await Promise.all([api(`/emby/Users/${user.Id}/Views`),api('/enhancements')]);if(view!=='browse')return;const heroId=libs.Items[0]?.Id||'';$('#app').innerHTML=`<div class="v5-home"><section class="v5-hero"><img class="v5-hero-bg" id="v5-hero-bg" src="${heroId?`/emby/Items/${esc(heroId)}/Images/Primary?MaxWidth=1400&api_key=${encodeURIComponent(token)}`:''}" alt=""><div class="v5-hero-copy"><div class="v5-eyebrow">MACA · CINEMA</div><h1 id="v5-hero-title">你的私人影库</h1><p id="v5-hero-overview">浏览媒体库并直接播放你的收藏。</p><button id="v5-browse">▶&nbsp;&nbsp;浏览媒体</button></div></section><div class="v5-content"><div class="v5-search"><select id="library" aria-label="媒体库"><option value="">全部媒体</option>${libs.Items.map(x=>`<option value="${esc(x.Id)}" ${parent===x.Id?'selected':''}>${esc(x.Name)}</option>`).join('')}</select><input id="search" aria-label="搜索媒体" placeholder="${enh.SearchByInitials?'搜索片名或拼音首字母…':'搜索片名…'}" value="${esc(term)}"><button id="searchBtn" class="secondary icon-button" title="搜索" aria-label="搜索"><svg viewBox="0 0 24 24"><path d="M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0"/></svg></button><button class="secondary icon-button" title="返回影库" aria-label="返回影库" onclick="browseRoot()"><svg viewBox="0 0 24 24"><path d="M3 11l9-8 9 8M5 10v11h14V10M9 21v-7h6v7"/></svg></button></div><section class="v5-section"><div class="v5-section-head"><h2>我的媒体</h2></div><div id="libraries" class="v5-library-shelf">${libs.Items.map(x=>`<article class="card library-card" role="button" tabindex="0" data-id="${esc(x.Id)}"><img loading="lazy" decoding="async" src="/emby/Items/${esc(x.Id)}/Images/Primary?MaxWidth=640&api_key=${encodeURIComponent(token)}"><strong>${esc(x.Name)}</strong></article>`).join('')}</div></section><section class="v5-section"><div class="v5-section-head"><h2 id="wall-heading">影视</h2></div><div id="wall" class="v5-wall"></div><div id="paging" class="paging"></div></section></div></div>`;document.querySelectorAll('.library-card').forEach(x=>x.onclick=run(async()=>{parent=x.dataset.id;page=0;$('#library').value=parent;await loadWall()}));$('#library').onchange=run(async e=>{parent=e.target.value;page=0;await loadWall()});$('#searchBtn').onclick=run(async()=>{term=$('#search').value.trim();page=0;await loadWall()});$('#search').onkeydown=e=>{if(e.key==='Enter')$('#searchBtn').click()};$('#v5-browse').onclick=()=>$('#wall').scrollIntoView({behavior:'smooth',block:'start'});await loadWall()}catch(e){toast(e.message)}}'''
s=re.sub(r'async function browse\(\)\{.*?\}\nlet wallCursors',browse+'\nlet wallCursors',s,flags=re.S,count=1)

loadwall=r'''async function loadWall(){$('#wall-heading').textContent=term?'搜索结果':($('#library').selectedOptions[0]?.textContent||'影视');const key=parent+"|"+term;if(page===0||key!==wallKey){wallCursors=[""];wallKey=key}const params=new URLSearchParams({Limit:60,Cursor:wallCursors[page]||"",EnableTotalRecordCount:"false",SearchTerm:term,ParentId:parent});if(term)params.set('Recursive','true');if(!parent)params.set('IncludeItemTypes','Movie,Series');const b=await api('/emby/Items?'+params);wallCursors[page+1]=b.NextCursor||'';$('#wall').innerHTML=b.Items.length?b.Items.map(x=>`<article class="card" data-id="${esc(x.Id)}" data-folder="${x.IsFolder}"><img loading="lazy" decoding="async" src="/emby/Items/${esc(x.Id)}/Images/Primary?MaxWidth=500&api_key=${encodeURIComponent(token)}" alt="${esc(x.Name)}"><strong>${esc(x.Name)}</strong><span class="muted">${x.IsFolder?'文件夹':x.ProductionYear||'直接播放'}</span></article>`).join(''):'<div class="empty">暂无媒体</div>';const first=b.Items.find(x=>!x.IsFolder)||b.Items[0];if(first){const bg=$('#v5-hero-bg');if(bg)bg.src=`/emby/Items/${esc(first.Id)}/Images/Primary?MaxWidth=1400&api_key=${encodeURIComponent(token)}`;if($('#v5-hero-title'))$('#v5-hero-title').textContent=first.Name||'你的私人影库';if($('#v5-hero-overview'))$('#v5-hero-overview').textContent=first.Overview||'浏览媒体库并直接播放你的收藏。'}$('#wall').querySelectorAll('.card').forEach(el=>el.onclick=run(async()=>{if(el.dataset.folder==='true'){parent=el.dataset.id;page=0;await loadWall()}else await detail(el.dataset.id)}));$('#paging').innerHTML=`<button class="secondary" id="prev" ${page===0?'disabled':''}>上一页</button><span class="muted">第 ${page+1} 页</span><button class="secondary" id="next" ${!b.HasMore?'disabled':''}>下一页</button>`;bindPosterMenus();$('#prev').onclick=run(async()=>{page--;await loadWall()});$('#next').onclick=run(async()=>{page++;await loadWall()})}'''
s=re.sub(r'async function loadWall\(\)\{.*?\}\n',loadwall+'\n',s,flags=re.S,count=1)

detail=r'''async function detail(i){const x=await api(`/emby/Users/${user.Id}/Items/${i}`);let selected=i,starting=false;const versions=x.MediaSources||[],primary=`/emby/Items/${i}/Images/Primary?MaxWidth=500&api_key=${encodeURIComponent(token)}`,backdrop=`/emby/Items/${i}/Images/Backdrop?MaxWidth=1600&api_key=${encodeURIComponent(token)}`;const d=$('#modal');d.className='v5-detail-dialog';d.innerHTML=`<section class="v5-detail-hero"><img class="v5-detail-backdrop" src="${backdrop}" onerror="this.onerror=null;this.src='${primary}'" alt=""><div class="v5-detail-shell"><img class="v5-detail-poster" src="${primary}" alt="${esc(x.Name)}"><div><span class="badge">DIRECT PLAY</span><h2 class="v5-detail-title">${esc(x.Name)}</h2><p>${esc(x.Overview||'暂无简介。')}</p><div class="v5-detail-actions"><button id="play">▶ 播放</button>${versions.length>1?`<button id="versions" class="secondary" aria-expanded="false">版本 ${versions.length}</button><select id="version-list" aria-label="选择视频版本" hidden>${versions.map((v,n)=>`<option value="${esc(v.Id)}">版本 ${n+1} · ${esc(v.Name)}</option>`).join('')}</select>`:''}${user.Policy.IsAdministrator?'<button class="secondary" id="probe">读取媒体信息</button>':''}<button class="secondary" onclick="closeModal()">关闭</button></div></div></div></section><div class="v5-detail-body"><section aria-label="演员"><h3>演员</h3><div class="actors">${(x.People||[]).filter(p=>p.Type==='Actor'&&(!x.HideMissingActorImages||p.PrimaryImageTag)).map(p=>`<figure class="actor">${p.PrimaryImageTag?`<img loading="lazy" decoding="async" src="/emby/Items/${encodeURIComponent(p.Id)}/Images/Primary?tag=${encodeURIComponent(p.PrimaryImageTag)}&api_key=${encodeURIComponent(token)}" alt="${esc(p.Name)}">`:'<div class="actor-placeholder"></div>'}<figcaption>${esc(p.Name)}<small>${esc(p.Role)}</small></figcaption></figure>`).join('')}</div></section>${mediaInfo(x)}<div id="player"></div><section id="v5-related"><h3>相关推荐</h3><div class="v5-related"></div></section></div>`;d.showModal();async function startPlayback(){if(starting)return;starting=true;$('#play').disabled=true;try{await stop();const b=await api(`/emby/Items/${selected}/PlaybackInfo`,'POST',{});const source=b.MediaSources.find(v=>v.Id===selected)||b.MediaSources[0];current=selected;$('#player').innerHTML='<video controls controlsList="nodownload" autoplay playsinline></video>';const v=$('#player video');const started=()=>{if(v.currentTime<=0||v.paused)return;v.removeEventListener('timeupdate',started);api('/Sessions/Playing/Progress','POST',{ItemId:selected,PositionTicks:Math.floor(v.currentTime*1e7),RunTimeTicks:Number.isFinite(v.duration)?Math.floor(v.duration*1e7):0}).catch(e=>toast(e.message))};v.addEventListener('timeupdate',started);v.src=source.DirectStreamUrl;v.onerror=()=>toast('浏览器无法解码此格式或视频源不可达，请使用外部 Emby 客户端。');clearInterval(heartbeat);heartbeat=setInterval(()=>api('/Sessions/Playing/Progress','POST',{ItemId:selected,PositionTicks:Math.floor(v.currentTime*1e7),RunTimeTicks:Number.isFinite(v.duration)?Math.floor(v.duration*1e7):0}).catch(e=>{v.pause();toast(e.message)}),30000);v.onended=()=>stop()}finally{starting=false;if($('#play'))$('#play').disabled=false}}$('#play').onclick=run(startPlayback);$('#versions')?.addEventListener('click',()=>{const list=$('#version-list');list.hidden=!list.hidden;$('#versions').setAttribute('aria-expanded',String(!list.hidden))});$('#version-list')?.addEventListener('change',run(async e=>{selected=e.target.value;const source=versions.find(v=>v.Id===selected);$('.media-info').outerHTML=mediaInfo({MediaSources:[source]});if(current)await startPlayback();toast('已切换版本：'+source.Name)}));$('#probe')?.addEventListener('click',run(async()=>{$('#probe').disabled=true;try{await api(`/emby/Items/${i}/RefreshMediaInfo`,'POST',{});toast('媒体信息已读取');await closeModal();await detail(i)}finally{if($('#probe'))$('#probe').disabled=false}}));const related=await api(`/emby/Items/${i}/Similar?Limit=6`);$('.v5-related').innerHTML=related.Items.map(v=>`<article class="card" data-id="${esc(v.Id)}"><img loading="lazy" decoding="async" src="/emby/Items/${esc(v.Id)}/Images/Primary?MaxWidth=360&api_key=${encodeURIComponent(token)}"><strong>${esc(v.Name)}</strong></article>`).join('');$('.v5-related').querySelectorAll('.card').forEach(el=>el.onclick=run(async()=>{await closeModal();await detail(el.dataset.id)}))}'''
s=re.sub(r'async function detail\(i\)\{.*?\}\n\nasync function stop',detail+'\n\nasync function stop',s,flags=re.S,count=1)

# Give the static shell the final product name without touching any API logic.
s=s.replace('<button class="logo" title="返回主页" onclick="token?browseRoot():login()">go-emby</button><span class="muted">私人影库</span>','<button class="logo" title="返回主页" onclick="token?browseRoot():login()">MACA</button>')

# Verify actual template functions were replaced.
for needle in ('v5-login-page','v5-home','v5-detail-dialog','function toggleTheme()','async function loadWall()'):
    if needle not in s: raise SystemExit('missing '+needle)
p.write_text(s)
